Actionscript.script:
import flash.display.BitmapData;
import flash.geom.Matrix;
import flash.geom.Point;
import flash.geom.Rectangle;
import flash.geom.ColorTransform;
import flash.filters.ColorMatrixFilter;
import flash.filters.GlowFilter;
stop();
var source:MovieClip=this.__radioSource;
var bitmap:BitmapData=new BitmapData(1024,576,true,0);
bitmap.draw(source,new Matrix());
bitmap.applyFilter(bitmap,bitmap.rectangle,new Point(),new ColorMatrixFilter([0.2197802667,0.3356672,0.03388586667,0,21.12,0.1034486588,0.4680079059,0.03513167059,0,41.36,0.1085844078,0.3652848941,0.1568757961,0,63.36,0,0,0,0.88,0]));
var scan:ColorTransform=new ColorTransform(0.84,0.84,0.84,1);
for(var scanY:Number=0;scanY<576;scanY+=3){
    bitmap.colorTransform(new Rectangle(0,scanY,1024,1),scan);
}
source._visible=false;
var picture:MovieClip=this.createEmptyMovieClip("__radioPicture",this.getNextHighestDepth());
picture.attachBitmap(bitmap,0,"auto",true);
picture.filters=[new GlowFilter(5214943,0.3,3.2,3.2,1,2,false,false)];
picture.cacheAsBitmap=true;
this.__radioBitmap=bitmap;
this.onUnload=function():Void{this.__radioBitmap.dispose();};
